        self.expected_items = expected_items
        self.false_positive_rate = false_positive_rate

        self.size = self._calculate_size()
        self.hash_count = self._calculate_hash_count()

        self.bit_array = bytearray((0,) * (self.size // 8 + 1))

    def _calculate_size(self) -> int:
        """Calculate the optimal size of the bit array (m) based on expected items and false positive rate."""
        return int(-1 * (expected_items * math.log(false_positive_rate) / (math.log(2) ** 2)))

    def _calculate_hash_count(self) -> int:
        """Calculate the optimal number of hash functions (k) using the bit array size."""
        return max(1, int((self.size / self.expected_items) * math.log(2)))

    def _bit_index(self, index: int) -> (int, int):
        """Compute the byte index and bit position in the bit array."""
        return index // 8, index % 8

    def _set_bit(self, index: int) -> None:
        """Set a bit at the specified index in the bit array."""
        byte_index, bit_position = self._bit_index(index)
        self.bit_array[byte_index] |= (1 << bit_position)

    def _get_bit(self, index: int) -> bool:
        """Get the value of a bit at the specified index in the bit array."""
        byte_index, bit_position = self._bit_index(index)
        return (self.bit_array[byte_index] & (1 << bit_position)) != 0

    def _hash_item(self, item: str, seed: int) -> int:
        """Hash the item with a particular seed and return the computed index in the bit array."""
        hash_digest = hashlib.md5(f"{item}-{seed}".encode()).hexdigest()
        return int(hash_digest, 16) % self.size

    def add(self, item: str) -> None:
        """Add an item to the Bloom filter, setting bits at the computed indices."""
        for i in range(self.hash_count):
            index = self._hash_item(item, i)
            self._set_bit(index)

    def contains(self, item: str) -> bool:
        """Check if an item is potentially in the Bloom filter."""
        return all(self._get_bit(self._hash_item(item, i)) for i in range(self.hash_count))

